## SqliteVectorStore.cs

Now stores a connection string instead of a `DbConnection`:

```csharp
public sealed class SqliteVectorStore : IVectorStore
{
    private readonly string _connectionString;
    private readonly SqliteVectorStoreOptions _options;

    public SqliteVectorStore(string connectionString, SqliteVectorStoreOptions? options = default)
    {
        Verify.NotNull(connectionString);
        this._connectionString = connectionString;
        this._options = options ?? new();
    }

    [Obsolete("Use the constructor that accepts a connection string instead.", error: true)]
    public SqliteVectorStore(DbConnection connection, SqliteVectorStoreOptions? options = default)
        => throw new InvalidOperationException("Use the constructor that accepts a connection string instead.");

    // GetCollection passes this._connectionString to factory/record collection

    public async IAsyncEnumerable<string> ListCollectionNamesAsync([EnumeratorCancellation] ...)
    {
        // ...
        using var connection = new SqliteConnection(this._connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);
        using var command = connection.CreateCommand();
        // ...
    }
}
```

**Connection lifecycle:** `ListCollectionNamesAsync` now creates, opens, and disposes its own connection per call.

## SqliteVectorStoreRecordCollection.cs

Key changes:

```csharp
private readonly string _connectionString;
private readonly string _vectorSearchExtensionName;

public SqliteVectorStoreRecordCollection(
    string connectionString,
    string collectionName,
    SqliteVectorStoreRecordCollectionOptions<TRecord>? options = default)
{
    Verify.NotNull(connectionString);
    // ...
    this._connectionString = connectionString;
    this._vectorSearchExtensionName = this._options.VectorSearchExtensionName ?? SqliteConstants.VectorSearchExtensionName;
    // ...
    this._commandBuilder = new SqliteVectorStoreCollectionCommandBuilder();
}

private async ValueTask<SqliteConnection> GetConnectionAsync(CancellationToken cancellationToken = default)
{
    var connection = new SqliteConnection(this._connectionString);
    await connection.OpenAsync(cancellationToken).ConfigureAwait(false);
    connection.LoadExtension(this._vectorSearchExtensionName);
    return connection;
}
```

**Connection lifecycle:** Every public operation now obtains a connection via `GetConnectionAsync` wrapped in `using`, opens it, loads the extension, and disposes it after the operation. Methods like `GetAsync`, `GetBatchAsync`, `UpsertAsync`, `DeleteAsync` became `async` and pass the connection down to `Internal*` helpers, which all now accept `SqliteConnection connection` as their first parameter.

## SqliteServiceCollectionExtensions.cs

```csharp
[Obsolete("Use AddSqliteVectorStore with connectionString instead.", error: true)]
public static IServiceCollection AddSqliteVectorStore(this IServiceCollection services, SqliteVectorStoreOptions? options = default, string? serviceId = default)
    => throw new InvalidOperationException("Use AddSqliteVectorStore with connectionString instead.");

public static IServiceCollection AddSqliteVectorStore(this IServiceCollection services, string connectionString, SqliteVectorStoreOptions? options = default, string? serviceId = default)
    => services.AddKeyedSingleton<IVectorStore>(serviceId, (sp, _) => new SqliteVectorStore(connectionString, options ?? sp.GetService<SqliteVectorStoreOptions>()));

[Obsolete("Use AddSqliteVectorStoreRecordCollection with connectionString instead.", error: true)]
public static IServiceCollection AddSqliteVectorStoreRecordCollection<TKey, TRecord>(this IServiceCollection services, string collectionName, SqliteVectorStoreRecordCollectionOptions<TRecord>? options = default, string? serviceId = default) where TKey : notnull
    => throw new InvalidOperationException("Use AddSqliteVectorStore with connectionString instead.");

public static IServiceCollection AddSqliteVectorStoreRecordCollection<TKey, TRecord>(this IServiceCollection services, string collectionName, string connectionString, ..., string? serviceId = default) where TKey : notnull
{
    services.AddKeyedSingleton<IVectorStoreRecordCollection<TKey, TRecord>>(
        serviceId,
        (sp, _) => (new SqliteVectorStoreRecordCollection<TRecord>(connectionString, collectionName, options ?? sp.GetService<SqliteVectorStoreRecordCollectionOptions<TRecord>>()) as IVectorStoreRecordCollection<TKey, TRecord>)!);
    AddVectorizedSearch<TKey, TRecord>(services, serviceId);
    return services;
}

private static void AddVectorizedSearch<TKey, TRecord>(IServiceCollection services, string? serviceId) where TKey : notnull
    => services.AddKeyedSingleton<IVectorizedSearch<TRecord>>(serviceId, (sp, _) => sp.GetRequiredKeyedService<IVectorStoreRecordCollection<TKey, TRecord>>(serviceId));
```

### Summary of key architectural changes

- **DI registration** switched from `AddKeyedTransient` to `AddKeyedSingleton` — safe now because instances only hold a connection string, not a live connection.
- **Old parameterless-connectionString overloads** are marked `[Obsolete(..., error: true)]` and throw `InvalidOperationException`.
- **Connection lifecycle** moved from a shared/injected connection to per-operation connections created from the connection string, opened, extension loaded, and disposed via `using`.
- The `GetExtensionName` helper and the `FakeDb*` test fakes were removed; unit tests that relied on a fake connection were disabled with `#if DISABLED` pending reimplementation as integration tests.

