namespace Microsoft.SemanticKernel.Connectors.Sqlite;

/// <summary>
/// Class for accessing the list of collections in a SQLite vector store.
/// </summary>
/// <remarks>
/// This class can be used with collections of any schema type, but requires you to provide schema information when getting a collection.
/// </remarks>
public class SqliteVectorStore : IVectorStore
{
    /// <summary>The connection string for the SQLite database represented by this <see cref="SqliteVectorStore"/>.</summary>
    private readonly string? _connectionString;

    /// <summary><see cref="DbConnection"/> that will be used to manage the data in SQLite.</summary>
    /// <remarks>Only set when the store is constructed via the obsolete constructor that accepts a <see cref="DbConnection"/>.</remarks>
    private readonly DbConnection? _connection;

    /// <summary>Optional configuration options for this class.</summary>
    private readonly SqliteVectorStoreOptions _options;

    /// <summary>
    /// Initializes a new instance of the <see cref="SqliteVectorStore"/> class.
    /// </summary>
    /// <param name="connectionString">The connection string to connect to the SQLite database with.</param>
    /// <param name="options">Optional configuration options for this class.</param>
    /// <remarks>
    /// The <see cref="SqliteVectorStore"/> manages the connection lifecycle internally: connections are created,
    /// opened and disposed as required for each operation.
    /// </remarks>
    public SqliteVectorStore(
        string connectionString,
        SqliteVectorStoreOptions? options = default)
    {
        Verify.NotNull(connectionString);

        this._connectionString = connectionString;
        this._options = options ?? new();
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="SqliteVectorStore"/> class.
    /// </summary>
    /// <param name="connection"><see cref="DbConnection"/> that will be used to manage the data in SQLite.</param>
    /// <param name="options">Optional configuration options for this class.</param>
    [Obsolete("Use the constructor that accepts a connection string instead. The library will manage the connection lifecycle internally.")]
    public SqliteVectorStore(
        DbConnection connection,
        SqliteVectorStoreOptions? options = default)
    {
        Verify.NotNull(connection);

        this._connection = connection;
        this._options = options ?? new();
    }

    /// <inheritdoc />
    public virtual IVectorStoreRecordCollection<TKey, TRecord> GetCollection<TKey, TRecord>(string name, VectorStoreRecordDefinition? vectorStoreRecordDefinition = null)
        where TKey : notnull
    {
#pragma warning disable CS0618 // ISqliteVectorStoreRecordCollectionFactory is obsolete
        if (this._options.VectorStoreCollectionFactory is not null)
        {
            var connection = this._connection ?? new SqliteConnection(this._connectionString);

            return this._options.VectorStoreCollectionFactory.CreateVectorStoreRecordCollection<TKey, TRecord>(
                connection,
                name,
                vectorStoreRecordDefinition);
        }
#pragma warning restore CS0618

        if (typeof(TKey) != typeof(string) && typeof(TKey) != typeof(ulong))
        {
            throw new NotSupportedException($"Only {nameof(String)} and {nameof(UInt64)} keys are supported.");
        }

        var options = new SqliteVectorStoreRecordCollectionOptions<TRecord>
        {
            VectorStoreRecordDefinition = vectorStoreRecordDefinition,
            VectorSearchExtensionName = this._options.VectorSearchExtensionName,
            VectorVirtualTableName = this._options.VectorVirtualTableName
        };

        var recordCollection = this._connectionString is not null
            ? new SqliteVectorStoreRecordCollection<TRecord>(this._connectionString, name, options)
#pragma warning disable CS0618 // Obsolete constructor kept for the DbConnection based store.
            : new SqliteVectorStoreRecordCollection<TRecord>(this._connection!, name, options);
#pragma warning restore CS0618

        return (recordCollection as IVectorStoreRecordCollection<TKey, TRecord>)!;
    }

    /// <inheritdoc />
    public virtual async IAsyncEnumerable<string> ListCollectionNamesAsync([EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string TablePropertyName = "name";
        const string Query = $"SELECT {TablePropertyName} FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%';";

        DbConnection connection = this._connection ?? new SqliteConnection(this._connectionString);
        var ownsConnection = this._connection is null;

        try
        {
            if (ownsConnection)
            {
                await connection.OpenAsync(cancellationToken).ConfigureAwait(false);
            }

            using var command = connection.CreateCommand();

            command.CommandText = Query;

            using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

            while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
            {
                var ordinal = reader.GetOrdinal(TablePropertyName);
                yield return reader.GetString(ordinal);
            }
        }
        finally
        {
            if (ownsConnection)
            {
                await connection.DisposeAsync().ConfigureAwait(false);
            }
        }
    }
}
